// Data reduction - VirusTotal quota
// VirusTotal's own counter for this API key (every caller: this stack, the
// dev environment, manual tests). claim_next_observable() budgets with the
// higher of this and the local count. The quota request itself is logged
// as provider "virustotal_quota", so it never inflates the local VirusTotal
// count; if VirusTotal counts it, its own counter shows it.
// Mode: Run Once for All Items.

const res = $json; // full HTTP response
const num = (v) => (Number.isFinite(Number(v)) ? Number(v) : null);
const daily = res.body?.data?.api_requests_daily?.user || {};
const ok = res.statusCode === 200 && num(daily.used) !== null;

return [{
  json: {
    ok,
    quota: ok ? { used: num(daily.used), allowed: num(daily.allowed), raw: res.body.data } : null,
    calls: [{
      provider: 'virustotal_quota',
      caller: 'monitor',
      endpoint: 'overall_quotas',
      http_status: Number.isInteger(res.statusCode) ? res.statusCode : null,
      message: ok ? null : String(res.body?.error?.message || res.error?.message || 'no quota in response').slice(0, 300),
    }],
  },
}];

