-- Providers over api_alert_threshold_pct today that were not e-mailed yet;
-- the function marks them, so each provider alerts once per UTC day.
SELECT provider, used, daily_limit FROM cyber_sentinel_ai.api_usage_alerts_due();

parameters.jsCode:
// Build e-mail
// One e-mail for all providers that crossed api_alert_threshold_pct today
// (each provider alerts once per UTC day, see api_usage_alerts_due()).
// Mode: Run Once for All Items.

const rows = $('Usage alerts due').all().map((i) => i.json).filter((r) => r.provider);
const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
const pct = (r) => Math.round((100 * Number(r.used)) / Number(r.daily_limit));

const lines = rows.map((r) => `<tr><td>${esc(r.provider)}</td><td align="right">${esc(r.used)}</td>`
  + `<td align="right">${esc(r.daily_limit)}</td><td align="right"><b>${pct(r)} %</b></td></tr>`).join('');

return [{
  json: {
    subject: `Cyber Sentinel: API usage ${rows.map((r) => `${r.provider} ${pct(r)}%`).join(', ')}`,
    html: `<p>Daily API usage crossed the alert threshold (UTC day, resets at 00:00 UTC):</p>
<table cellpadding="4" border="1" style="border-collapse:collapse">
<tr><th>Provider</th><th>Used</th><th>Daily limit</th><th>Share</th></tr>${lines}</table>
<p>Used = the higher of the local count (api_call_log) and the provider's own counter.
Details: AI Config UI, page <i>API usage</i>. VirusTotal stops by itself when the budget is used up;
the other providers are only counted.</p>`,
  },
}];
